<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue';
import {state,t,go,api,list,date,human,notify,sanitize,testTypeCodes,testTypeName,testTypeCode,testPolicy,testDuration} from '../store';
import Icon from './Icon.vue';
import ScoreChart from './ScoreChart.vue';
import ResultInsights from './ResultInsights.vue';
import TestTypeCards from './TestTypeCards.vue';
const path=state.path,part=path.split('/').filter(Boolean),page=part[0],id=part[1];
const loading=ref(true),busy=ref(false),error=ref(''),data=ref(null),items=ref([]),agree=ref(false),search=ref(''),accessCode=ref('');
const checks=ref({online:navigator.onLine,connection:'checking',latency:null,storage:null,speaker:'untested',microphone:'untested',microphoneError:''}),checkingConnection=ref(false),checkingMicrophone=ref(false);let audioContext;
const hasSpeaking=computed(()=>packageData.value.sections?.some(s=>String(s.competency?.code||state.competencies.find(c=>c.id===s.competency_id)?.code||'').toLowerCase()==='speaking'));
async function checkReadiness(){checkingConnection.value=true;checks.value.online=navigator.onLine;checks.value.connection='checking';try{if(!navigator.onLine)throw new Error('offline');const started=performance.now();await api('/bootstrap');checks.value.latency=Math.round(performance.now()-started);checks.value.connection='connected'}catch(e){checks.value.connection='unavailable'}finally{checkingConnection.value=false}try{const key='inbaf-readiness-'+Date.now();localStorage.setItem(key,'ready');checks.value.storage=localStorage.getItem(key)==='ready';localStorage.removeItem(key)}catch(e){checks.value.storage=false}}
async function testSpeaker(){try{const Context=window.AudioContext||window.webkitAudioContext;if(!Context)throw new Error('unsupported');audioContext=audioContext||new Context();await audioContext.resume();const tone=audioContext.createOscillator(),gain=audioContext.createGain();tone.type='sine';tone.frequency.value=523.25;gain.gain.setValueAtTime(0,audioContext.currentTime);gain.gain.linearRampToValueAtTime(.08,audioContext.currentTime+.025);gain.gain.linearRampToValueAtTime(0,audioContext.currentTime+.35);tone.connect(gain);gain.connect(audioContext.destination);tone.start();tone.stop(audioContext.currentTime+.4);checks.value.speaker='played'}catch(e){checks.value.speaker='unavailable'}}
async function testMicrophone(){checkingMicrophone.value=true;checks.value.microphoneError='';try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Microphone access requires HTTPS or localhost and a supported browser.');const stream=await navigator.mediaDevices.getUserMedia({audio:true});checks.value.microphone=stream.getAudioTracks().some(track=>track.readyState==='live')?'ready':'unavailable';stream.getTracks().forEach(track=>track.stop())}catch(e){checks.value.microphone='unavailable';checks.value.microphoneError=e.message}finally{checkingMicrophone.value=false}}
const profile=ref({...state.user,profile:{...(state.user?.profile||{})}});
const queryType=()=>new URLSearchParams(state.query).get('test_type');
const selectedType=ref(testTypeCodes.includes(queryType())?queryType():'certification');
const filtered=computed(()=>items.value.filter(p=>testTypeCode(p)===selectedType.value&&JSON.stringify(p).toLowerCase().includes(search.value.toLowerCase())));
const policy=computed(()=>testPolicy(packageData.value));
const resultType=computed(()=>testTypeCode(data.value));
const review=computed(()=>list(data.value?.review_answers));
const resultLevel=computed(()=>data.value?.result?.level_name||data.value?.result?.level?.name||(typeof data.value?.level==='object'?data.value.level?.name:data.value?.level)||t('pending'));
const resultScore=computed(()=>data.value?.score??data.value?.result?.total_score??'--');
const attemptsLabel=computed(()=>Number(policy.value.attempts_limit)>0?policy.value.attempts_limit:t('attemptUnlimited'));
const placementLevels=computed(()=>(policy.value.level_thresholds||[]).map(level=>level.code||level.name).filter(Boolean).join(' / '));
function selectType(code){selectedType.value=code;go('/'+page+'?test_type='+code)}
function reviewLabel(item,fallback=''){const label=typeof item==='object'?(item?.text??item?.label??fallback):item??fallback;return new DOMParser().parseFromString(String(label),'text/html').body.textContent||String(fallback)}
function reviewResponse(value,question,choices=question.options||[]){
 if(value===null||value===undefined||value==='')return '--';
 if(Array.isArray(value))return value.map(entry=>reviewResponse(entry,question,choices)).join(', ');
 if(typeof value==='object'){
  if(value.url||value.recording_id||value.media_asset_id)return state.language==='id'?'Respons rekaman':'Recorded response';
  if(Object.keys(value).length===1&&Object.hasOwn(value,'answer'))return reviewResponse(value.answer,question,choices);
  const metadata=question.metadata||{},matching=['matching','drag_drop'].includes(question.type);
  const left=metadata.left_items||question.options||[],right=metadata.right_items||metadata.matches||metadata.right_options||question.options||[];
  return Object.entries(value).map(([key,entry])=>{const blank=(metadata.blanks||[]).find(item=>String(item.id)===key),item=blank||left.find((item,index)=>String(item.id??index)===key);return reviewLabel(item,key)+': '+reviewResponse(entry,question,matching?right:blank?.options||choices)}).join(', ');
 }
 if(question.type==='true_false'&&['true','false'].includes(String(value)))return String(value)==='true'?(state.language==='id'?'Benar':'True'):(state.language==='id'?'Salah':'False');
 const option=choices.find((entry,index)=>String(typeof entry==='object'?entry.id??index:index)===String(value));
 return option!==undefined?reviewLabel(option,String(value)):String(value);
}
function hasCorrectAnswer(question){if(['essay','speaking'].includes(question.type)||question.metadata?.manual)return false;const answer=question.answer_schema?.correct??question.answer_schema?.accepted;return answer!==null&&answer!==undefined&&answer!==''&&(!Array.isArray(answer)||answer.length>0)}
watch(()=>state.query,()=>{const code=queryType();if(testTypeCodes.includes(code))selectedType.value=code;if(page==='results'&&!id)load()});

const scores=computed(()=>list(data.value?.result?.competency_scores||data.value?.competency_scores));
const pending=computed(()=>data.value?.status==='pending_review'||data.value?.result?.manual_pending);
const packageData=computed(()=>data.value?.package||data.value||{});
let loadRevision=0;
async function load(){const revision=++loadRevision;loading.value=true;error.value='';try{if(page==='tests'){const all=await api('/packages');if(revision!==loadRevision)return;items.value=list(all);data.value=id?items.value.find(p=>String(p.id)===id):null;if(id){try{const response=await api('/packages/'+id);if(revision===loadRevision)data.value=response}catch(e){if(!data.value)throw e}}}else if(page==='results'){const response=await api('/results'+(id?'/'+id:'?test_type='+selectedType.value));if(revision!==loadRevision)return;if(id)data.value={...response.attempt,previous_result:response.previous_result,review_answers:response.review_answers||[],result:response.result||response.attempt?.result,certificate:response.certificate||response.attempt?.certificate};else items.value=list(response)}else if(page==='certificates'){const response=await api('/certificates');if(revision===loadRevision)items.value=list(response)}}catch(e){if(revision===loadRevision)error.value=e.message}finally{if(revision===loadRevision)loading.value=false}}
async function start(){busy.value=true;try{if(policy.value.require_fullscreen&&!document.fullscreenElement)await document.documentElement.requestFullscreen().catch(()=>{});const response=await api('/packages/'+id+'/attempts',{method:'POST',body:{access_code:accessCode.value}});go('/exam/'+(response.attempt?.id||response.attempt?.uuid||response.id||response.uuid))}catch(e){error.value=e.message;notify(e.message,true)}finally{busy.value=false}}
function certificateStatus(c){if(c.status==='revoked')return 'revoked';if(c.expires_at&&new Date(c.expires_at).getTime()<Date.now())return 'expired';return c.status||'valid'}
async function saveProfile(){busy.value=true;try{const response=await api('/profile',{method:'PUT',body:{name:profile.value.name,email:profile.value.email,...profile.value.profile}});state.user=response.user||response;notify(t('saveSuccess'))}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(async()=>{await load();if(page==='tests'&&id)checkReadiness()});onBeforeUnmount(()=>audioContext?.close().catch(()=>{}));
</script>
<template>
<section class="participant-page" :aria-busy="loading">
<div class="page-heading"><div><div class="eyebrow"><span></span>{{t('journey')}}</div><h1>{{id&&page==='tests'?t('readyDetail'):id&&page==='results'?'Your progress, made visible.':t(page)}}</h1><p>{{page==='tests'?t('recommendedSub'):page==='results'?'Every achievement tells a story. Here is yours.':page==='certificates'?'A meaningful achievement. Ready to share with the world.':'The person behind your next achievement.'}}</p></div><button v-if="id" class="button secondary" @click="go('/'+page+'?test_type='+(data?testTypeCode(data):selectedType))"><Icon name="ArrowLeft" :size="17"/>{{t('back')}}</button></div>
<div v-if="error" class="inline-error" role="alert"><span>{{error}}</span><button v-if="!busy" class="text-button" @click="load">{{state.language==='id'?'Coba lagi':'Try again'}}<Icon name="RefreshCw" :size="18"/></button></div><div v-if="loading" class="panel loading-panel" role="status"><span class="loader"></span>{{t('loading')}}</div>
<template v-else-if="page==='tests'&&!id"><TestTypeCards :packages="items" :selected="selectedType" select-only @select="selectType"/><div class="type-history-heading"><h2>{{testTypeName(selectedType)}}</h2><button class="text-button" @click="go('/results?test_type='+selectedType)">{{t(selectedType+'History')}}<Icon name="ArrowRight" :size="18"/></button></div><div class="list-toolbar"><div class="search-input"><Icon name="Search" :size="18"/><input v-model="search" :placeholder="t('search')" aria-label="Search assessments"></div><span class="muted" role="status">{{filtered.length}} {{t('availablePackages')}}</span></div><div class="package-grid test-grid"><article v-for="(p,i) in filtered" :key="p.id" class="package-card"><div class="package-top"><span class="package-icon" :class="['blue','cyan','purple'][i%3]"><Icon :name="['BookOpen','GraduationCap','BriefcaseBusiness'][i%3]" :size="28"/></span><span class="badge green">{{testTypeName(testTypeCode(p))}}</span></div><span class="eyebrow">{{p.code}}</span><h3>{{p.name}}</h3><p>{{p.description}}</p><div class="package-meta"><span><Icon name="Clock3" :size="15"/>{{testDuration(p)}}</span><span><Icon name="Shapes" :size="15"/>{{p.sections_count??p.sections?.length??state.competencies.length}} {{t('skills')}}</span></div><div class="package-feature"><Icon name="BadgeCheck" :size="16"/>{{testTypeCode(p)==='certification'&&p.certificate_enabled?t('eligibleCertificate'):t('noOfficialCertificate')}}</div><button class="button full" @click="go('/tests/'+p.id)">{{t('view')}}<Icon name="ArrowUpRight" :size="17"/></button></article></div><div v-if="!filtered.length" class="panel empty-state"><Icon name="BookOpen" :size="38"/><h3>{{t('empty')}}</h3><p>Published assessments will appear here.</p></div></template>
<template v-else-if="page==='tests'&&id&&data"><div class="readiness-grid"><div><section class="panel readiness-main"><span class="package-icon blue"><Icon name="BookOpen" :size="30"/></span><span class="badge neutral">{{testTypeName(testTypeCode(packageData))}}</span><div class="eyebrow">{{packageData.code}}</div><h2>{{packageData.name}}</h2><p>{{packageData.description}}</p><div class="readiness-metrics"><div><Icon name="Clock3"/><strong>{{policy.timer_enabled===false?t('noTimerDetail'):packageData.duration_minutes}}</strong><span>{{policy.timer_enabled===false?t('untimed'):t('duration')}}</span></div><div><Icon name="Shapes"/><strong>{{packageData.sections?.length||packageData.sections_count||'—'}}</strong><span>{{t('skills')}}</span></div><div><Icon name="Target"/><strong>{{testTypeCode(packageData)==='placement'?placementLevels||'--':packageData.pass_score}}</strong><span>{{testTypeCode(packageData)==='placement'?t('level'):t('passScore')}}</span></div></div><div class="readiness-policy"><h3>{{t('testPurpose')}}</h3><p>{{(state.language==='en'?policy.description_en:policy.description)||t(testTypeCode(packageData)+'Description')}}</p><div class="policy-chip-list"><span class="badge neutral">{{t('attemptPolicy')}}: {{attemptsLabel}}</span><span v-if="policy.require_fullscreen" class="badge amber">{{t('fullscreenRequired')}}</span><span v-if="packageData.requires_access_code" class="badge amber">{{t('accessCodeRequired')}}</span><span class="badge neutral">{{policy.timer_enabled===false?t('untimed'):t('timed')}}</span></div></div><h3>{{t('assessmentSections')}}</h3><div v-for="(s,i) in packageData.sections||[]" :key="s.id" class="readiness-section"><span>{{String(i+1).padStart(2,'0')}}</span><div><strong>{{s.title||s.competency?.name}}</strong><small>{{s.question_count||s.questions_count||s.question_ids?.length||'—'}} questions · {{s.duration_minutes||'—'}} min</small></div><span class="badge neutral">{{(s.weight/Math.max(1,packageData.sections.reduce((sum,row)=>sum+Number(row.weight),0))*100).toFixed(1)}}% weight</span></div><div class="panel-note"><Icon name="BadgeCheck" :size="17"/>{{testTypeCode(packageData)==='certification'&&packageData.certificate_enabled?t('eligibleCertificate'):t('noOfficialCertificate')}}</div></section></div><aside class="panel readiness-aside"><span class="metric-icon cyan"><Icon name="Sparkles" :size="24"/></span><h2>{{testTypeCode(packageData)==='practice'?t('practiceReadinessTitle'):t('readyTitle')}}</h2><p>{{testTypeCode(packageData)==='practice'?t('practiceReadinessText'):t('readyText')}}</p><div class="readiness-checks" aria-live="polite"><div class="readiness-checks-heading"><h4>Device & connection check</h4><button class="icon-button" @click="checkReadiness" :disabled="checkingConnection" aria-label="Retry readiness checks"><Icon name="RefreshCw" :size="15"/></button></div><div class="readiness-check-row"><Icon :name="checks.connection==='connected'?'CircleCheck':checks.connection==='checking'?'LoaderCircle':'CircleAlert'" :size="16"/><span>Server connection<small>{{checks.connection==='connected'?checks.latency+' ms round trip':checks.connection==='checking'?'Checking...':checks.online?'Server unavailable. Retry the check.':'You are offline.'}}</small></span></div><div class="readiness-check-row"><Icon :name="checks.storage?'CircleCheck':'CircleAlert'" :size="16"/><span>Answer recovery storage<small>{{checks.storage===null?'Checking...':checks.storage?'Available on this device':'Unavailable. Keep your connection active.'}}</small></span></div><div class="readiness-check-row"><Icon name="Volume2" :size="16"/><span>Speaker output<small>{{checks.speaker==='played'?'Test tone played. Confirm you can hear it.':checks.speaker==='unavailable'?'Audio output unavailable. Check your browser.':'Play a short tone to check your speakers.'}}</small></span><button class="button small secondary" @click="testSpeaker">Test sound</button></div><div v-if="hasSpeaking" class="readiness-check-row"><Icon name="Mic" :size="16"/><span>Microphone permission<small>{{checks.microphone==='ready'?'Access allowed. Microphone released.':checks.microphoneError||'Your permission is needed for speaking tasks.'}}</small></span><button class="button small secondary" @click="testMicrophone" :disabled="checkingMicrophone">{{checkingMicrophone?'Checking...':checks.microphone==='ready'?'Check again':'Check mic'}}</button></div><small class="readiness-check-note">These optional checks do not upload audio or start your assessment timer.</small></div><h4>{{t('guidelines')}}</h4><label v-if="packageData.requires_access_code" class="access-code-field">Assessment access code<input v-model="accessCode" autocomplete="off" required placeholder="Enter your institution&apos;s access code"></label><ul class="guideline-list"><li><Icon name="Check" :size="16"/>Use a stable internet connection.</li><li><Icon name="Check" :size="16"/>Allow microphone access for speaking.</li><li v-if="policy.security_monitoring"><Icon name="Check" :size="16"/>{{state.language==='id'?'Tetap di jendela ini selama ujian.':'Stay in this window throughout the test.'}}</li><li><Icon name="Check" :size="16"/>{{policy.timer_enabled===false?t('untimedGuideline'):state.language==='id'?'Waktu ujian dimulai saat Anda menekan Mulai.':'Your timer starts when you begin.'}}</li></ul><label class="checkbox-label"><input v-model="agree" type="checkbox"><span>{{t('agree')}}</span></label><button class="button full" :disabled="!agree||busy||(packageData.requires_access_code&&!accessCode.trim())" @click="start">{{busy?t('loading'):t(testTypeCode(packageData)==='practice'?'startPractice':testTypeCode(packageData)==='placement'?'startPlacement':'startCertification')}}<Icon name="ArrowRight" :size="18"/></button><div class="auth-security"><Icon name="ShieldCheck" :size="15"/>{{t('security')}}</div></aside></div></template>
<template v-else-if="page==='results'&&!id"><nav class="type-tabs" :aria-label="t('testType')"><button v-for="code in testTypeCodes" :key="code" :aria-pressed="selectedType===code" :class="{active:selectedType===code}" @click="selectType(code)">{{t(code+'History')}}</button></nav><p class="type-history-note">{{t('typeResultNote')}}</p><div v-if="!filtered.length" class="panel empty-state"><Icon name="ChartNoAxesCombined" :size="42"/><h3>A new chapter is waiting.</h3><p>{{t('noResults')}}</p><button class="button" @click="go('/tests')">{{t('browse')}}<Icon name="ArrowUpRight" :size="16"/></button></div><div v-else class="panel"><div class="table-scroll" tabindex="0" role="region" :aria-label="t('results')"><table><thead><tr><th>Assessment</th><th>Date</th><th>{{t('status')}}</th><th>{{t('score')}}</th><th>{{t('level')}}</th><th></th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td><span class="table-title"><span class="table-file"><Icon name="FileCheck2" :size="20"/></span>{{r.package?.name||r.package_name}}</span></td><td>{{date(r.submitted_at||r.created_at)}}</td><td><span class="badge" :class="r.status==='completed'?'green':'amber'">{{human(r.status)}}</span></td><td class="table-score">{{r.score??'—'}}</td><td>{{typeof r.level==='object'?r.level?.name:r.level||'—'}}</td><td><button class="text-button" @click="go(r.status==='in_progress'?'/exam/'+r.id:'/results/'+r.id)">{{r.status==='in_progress'?t('continue'):t('viewResults')}}<Icon name="ArrowUpRight" :size="15"/></button></td></tr></tbody></table></div></div></template>
<template v-else-if="page==='results'&&id&&data"><div v-if="pending" class="notice-banner"><Icon name="Clock3"/>{{t('scorePending')}}</div><section class="result-hero"><div><div class="banner-label"><Icon name="Sparkles" :size="16"/>{{testTypeName(resultType)}}</div><h2>{{data.package?.name||data.package_name}}</h2><p>{{date(data.submitted_at||data.created_at)}} · {{human(data.status)}}</p><span class="result-level">{{resultLevel}}</span></div><div class="result-score"><strong>{{pending?'—':data.score??data.result?.total_score??'—'}}</strong><span>{{t(resultType==='practice'?'practiceScore':resultType==='placement'?'score':'certificationScore')}} / {{data.result?.score_max||100}}</span></div></section><p v-if="resultType==='placement'" class="notice-banner">{{t('placementDisclaimer')}}</p><ResultInsights v-if="!pending&&data.result" :result="data.result" :previous="data.previous_result"/><section v-if="!pending&&(resultType!=='certification'||review.length)" class="panel answer-review"><div class="panel-heading"><div><h3>{{t('reviewAnswers')}}</h3><p>{{t('learningReview')}}</p></div><Icon name="BookOpenCheck"/></div><p v-if="!review.length" class="panel-review-note">{{t('noReview')}}</p><details v-for="(question,i) in review" :key="question.key" class="review-question"><summary>{{t('question')}} {{i+1}} <span>{{question.score??'--'}} {{t('score')}}</span></summary><div class="rich-content" v-html="sanitize(question.prompt)"></div><dl><div><dt>{{t('yourAnswer')}}</dt><dd>{{reviewResponse(question.response,question)}}</dd></div><div v-if="hasCorrectAnswer(question)"><dt>{{t('correctAnswer')}}</dt><dd>{{reviewResponse(question.answer_schema.correct??question.answer_schema.accepted,question)}}</dd></div></dl><div v-if="question.explanation"><h4>{{t('explanation')}}</h4><div class="rich-content" v-html="sanitize(question.explanation)"></div></div><p v-if="question.feedback">{{question.feedback}}</p></details></section><div v-if="!pending && scores.length" class="result-chart-grid"><section class="panel"><div class="panel-heading"><div><h3>Your skills at a glance</h3><p>A balanced view of your Indonesian proficiency.</p></div><Icon name="Radar" class="muted"/></div><ScoreChart :scores="scores" radar/></section><section class="panel"><div class="panel-heading"><div><h3>Competency breakdown</h3><p>Find strengths and discover room to grow.</p></div><Icon name="ChartNoAxesColumn" class="muted"/></div><ScoreChart :scores="scores"/></section></div><section v-if="!pending" class="panel score-breakdown"><div class="panel-heading"><div><h3>Every skill, in focus.</h3><p>Your results reflect the assessment rules recorded when you started.</p></div></div><div class="table-scroll" tabindex="0" role="region" :aria-label="t('results')"><table><thead><tr><th>{{t('competencies')}}</th><th>{{t('score')}}</th><th>{{t('weight')}}</th></tr></thead><tbody><tr v-for="s in scores" :key="s.competency_id"><td><strong>{{s.name}}</strong></td><td><div class="score-bar-cell"><span class="score-track"><i :style="{width:(s.normalized_score??(s.score/(data.result?.score_max||100)*100))+'%'}"></i></span><strong>{{s.score??'—'}}</strong></div></td><td>{{s.weight_percentage??(s.weight/Math.max(1,scores.reduce((sum,row)=>sum+Number(row.weight),0))*100).toFixed(1)}}%</td></tr></tbody></table></div></section><div class="result-actions"><button class="button secondary" @click="go('/dashboard')">{{t('returnDashboard')}}<Icon name="ArrowRight" :size="17"/></button><a v-if="resultType==='placement'&&!pending" :href="'/api/results/'+id+'/placement-report'" class="button" target="_blank" rel="noopener">{{t('printPlacement')}}<Icon name="Download" :size="17"/></a><a v-if="resultType==='certification'&&data.certificate" :href="'/api/certificates/'+data.certificate.id+'/pdf'" class="button" target="_blank" rel="noopener">{{t('print')}}<Icon name="Download" :size="17"/></a></div></template>
<template v-else-if="page==='certificates'"><div v-if="!items.length" class="panel empty-state"><Icon name="Award" :size="45"/><h3>Achievement looks good on you.</h3><p>{{t('noCertificates')}}</p><button class="button" @click="go('/tests')">{{t('browse')}}</button></div><div v-else class="certificate-grid"><article v-for="c in items" :key="c.id" class="panel certificate-card"><div class="certificate-visual"><img src="/brand/favicon.svg" alt="INBAF"><span>CERTIFICATE OF PROFICIENCY</span><strong>{{c.payload?.holder_name||c.attempt?.snapshot?.participant_name||'—'}}</strong><small>{{c.attempt?.package?.name||c.package?.name||c.package_name}}</small><span class="certificate-seal"><Icon name="Award" :size="37"/></span></div><div class="certificate-body"><span class="badge" :class="certificateStatus(c)==='valid'?'green':'red'">{{human(certificateStatus(c))}}</span><h3>{{c.number||c.certificate_number}}</h3><p>{{date(c.issued_at)}} <span v-if="c.expires_at"> · Expires {{date(c.expires_at)}}</span></p><div class="certificate-buttons"><a :href="'/api/certificates/'+c.id+'/pdf'" target="_blank" rel="noopener" class="button"><Icon name="Download" :size="16"/>PDF</a><button class="button secondary" @click="go('/verify/'+(c.verification_token||c.token))"><Icon name="ShieldCheck" :size="16"/>{{t('verify')}}</button></div></div></article></div></template>
<template v-else-if="page==='profile'"><div class="profile-grid"><aside class="panel profile-summary"><span class="large-avatar">{{state.user?.name?.split(' ').map(n=>n[0]).slice(0,2).join('')}}</span><h2>{{state.user?.name}}</h2><p>{{state.user?.email}}</p><span class="badge blue">{{human(state.user?.role)}}</span><div class="panel-note"><Icon name="ShieldCheck" :size="17"/>Keep your profile accurate for your assessment records and certificates.</div></aside><form class="panel profile-form" @submit.prevent="saveProfile"><div class="panel-heading"><div><h3>Your personal details</h3><p>A little about you and where you are headed.</p></div><Icon name="CircleUserRound" class="muted"/></div><div class="form-grid"><label>{{t('name')}}<input v-model="profile.name" required maxlength="120"></label><label>{{t('email')}}<input v-model="profile.email" type="email" required></label><label v-for="field in ['country','nationality','native_language','institution']" :key="field">{{t(field)}}<input v-model="profile.profile[field]" maxlength="180"></label></div><div class="form-footer"><button class="button" :disabled="busy">{{busy?t('loading'):t('save')}}<Icon name="Check" :size="17"/></button></div></form></div></template>
<template v-else><div class="panel empty-state"><Icon name="MapPin" :size="40"/><h2>Let us get you back on track.</h2><button class="button" @click="go('/dashboard')">{{t('returnDashboard')}}</button></div></template>
</section>
